    private function t(string $ar,string $en): string{return $this->ar?$ar:$en;}
    private static function e($v): string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
    private function label(string $key): string{return self::LABELS[$key][$this->ar?0:1]??$key;}
    private function url(array $extra=[]): string{$base=['lang'=>$this->lang,'office'=>$this->s['office'],'view'=>$this->s['view']];if($this->s['view']==='advances')$base['kind']=$this->s['kind'];if($this->s['view']==='reports'&&$this->s['report'])$base+=['from'=>$this->s['report']['from'],'to'=>$this->s['report']['to'],'kind'=>$this->s['report']['filter'],'status'=>$this->s['report']['status']];return 'workspace.php?'.http_build_query(array_replace($base,$extra));}
    private function status(string $status): string {return ['draft'=>$this->t('مسودة · غير مسجلة ماليًا','Draft · not posted'),'active'=>$this->t('نشط','Active'),'archived'=>$this->t('مؤرشف','Archived')][$status]??$status;}
    private function name(int $id): string {foreach($this->s['staff']as$p)if($p['id']===$id)return trim($p['name'])!==''?$p['name']:$p['login'];return '#'.$id;}
    private function money(string $value,string $currency): string{return '<bdi>'.self::e($value.' '.$currency).'</bdi>';}
    private function hidden(string $name,$value): string{return '<input type="hidden" name="'.self::e($name).'" value="'.self::e($value).'">';}
    private function tokens(string $action,string $kind,string $id='',int $revision=0): string
    {
        $h='';foreach(['token'=>$this->csrf,'action'=>$action,'view'=>$this->s['view'],'kind'=>$kind,'office'=>$this->s['office'],'lang'=>$this->lang,'id'=>$id,'revision'=>$revision]as$k=>$v)$h.=$this->hidden($k,$v);return $h;
    }
    public function render(array $state,string $csrf): string
    {
        $this->s=$state;$this->lang=$state['language'];$this->ar=$this->lang==='ar';$this->csrf=$csrf;
        $nav=OfficeExpenseStaffPage::navigation($this->lang,$state['view'],!empty($state['manage_staff']),$state['office'],true);
        $bufferLevel=ob_get_level();ob_start();try{ ?>
<div class="office-expenses-app workspace-app" lang="<?= $this->lang ?>" dir="<?= $this->ar?'rtl':'ltr' ?>"><div class="app-layout"><aside class="app-sidebar" aria-label="<?= $this->t('القائمة الرئيسية','Main menu') ?>"><a class="brand" href="<?= self::e('index.php?lang='.$this->lang.'&office='.$state['office'].'&view=overview') ?>"><span class="brand-icon"><i class="fa-solid fa-coins" aria-hidden="true"></i></span><span><b><?= $this->t('فينانس ساس','Finens SaaS') ?></b><small><?= $this->t('لوحة تحكم الشركات','Company dashboard') ?></small></span></a><nav><?= $nav ?></nav></aside><div class="app-content"><header class="app-navbar"><div class="company-context"><span class="company-icon"><i class="fa-solid fa-building" aria-hidden="true"></i></span><div><strong>China Planet</strong><small><?= $this->t($state['office']==='china'?'فرع الصين':'فرع مصر',$state['office']==='china'?'China office':'Egypt office') ?></small></div></div><a class="language-link" href="<?= self::e($this->url(['lang'=>$this->ar?'en':'ar','edit'=>$state['selected']['id']??null])) ?>"><?= $this->ar?'English':'العربية' ?></a></header><details class="workspace-mobile-menu"><summary><i class="fa-solid fa-bars" aria-hidden="true"></i> <?= $this->t('القائمة الرئيسية','Main menu') ?></summary><nav><?= $nav ?></nav></details><main>
<div class="page-heading"><div><h1><?= self::e($this->label($state['view'])) ?></h1><p><?= $this->t('متابعة وإدارة بيانات الفرع وصلاحياته','Manage the records and permissions of this branch') ?></p></div><div class="workspace-heading-actions"><?php if($state['view']!=='reports'&&($state['permissions']['create']??false)){ ?><a class="button button-brand" href="<?= self::e($this->url(['edit'=>null])) ?>#workspace-form"><i class="fa-solid fa-plus" aria-hidden="true"></i> <?= $this->t('إضافة جديد','Add new') ?></a><?php } ?></div></div>
<form method="get" action="workspace.php" class="workspace-branch"><input type="hidden" name="lang" value="<?= $this->lang ?>"><input type="hidden" name="view" value="<?= self::e($state['view']) ?>"><label for="workspace-office"><?= $this->t('الفرع','Branch') ?></label><select id="workspace-office" name="office"><?php foreach($state['offices']as$office=>$currencies){ ?><option value="<?= $office ?>"<?= $state['office']===$office?' selected':'' ?>><?= $this->t($office==='china'?'الصين':'مصر',ucfirst($office)) ?></option><?php } ?></select><button class="button button-muted" type="submit"><?= $this->t('عرض الفرع','View branch') ?></button></form>
<?php if($state['error']){ ?><div class="flash error" role="alert"><?= $this->t('لم يُؤكد حفظ الطلب. تحقق من الصلاحية والحقول والتاريخ، ثم أعد فتح السجل قبل المحاولة.','The request was not confirmed. Check access, fields and dates, then reopen the record before retrying.') ?></div><?php if($state['form']){ ?><details class="workspace-card"><summary><?= $this->t('البيانات المُرسلة لإعادة المحاولة','Submitted values for retry') ?></summary><dl><?php foreach($state['form']as$k=>$v)if(is_string($v)){ ?><dt><?= self::e($k) ?></dt><dd><?= self::e($v) ?></dd><?php } ?></dl></details><?php } }else{
if(in_array($state['view'],['expenses','advances','treasury','receipts','payroll','reports'],true)){ ?><p class="workspace-notice"><?= $this->t('الطلبات هنا مسودات للمراجعة؛ لا تغيّر رصيد الخزنة ولا تمثل مبالغ مدفوعة. الدفع والترحيل المالي غير مفعّلين بعد.','Requests here are review drafts. They do not change cash balances or represent payments. Payments and financial posting are not enabled yet.') ?></p><?php }
if($state['print']){$this->printDocument($state['selected']);}
elseif($state['view']==='reports'){$this->reports();}
else{
if($state['view']==='treasury')$this->treasury();
if($state['view']==='employees')$this->employeeDirectory();
if($state['view']==='settings'){$this->letterhead($state['selected']['content']??['name'=>'China Planet','phone'=>'']);$this->cashAccounts();}
if($state['view']==='categories')$this->categories();else $this->register();
if($state['view']==='advances'){ ?><div class="workspace-tabs"><a href="<?= self::e($this->url(['kind'=>'advance','edit'=>null])) ?>#workspace-form"><?= $this->t('عهدة جديدة','New advance') ?></a><a href="<?= self::e($this->url(['kind'=>'advance_return','edit'=>null])) ?>#workspace-form"><?= $this->t('مرتجع عهدة','Return an advance') ?></a></div><?php }
$this->form();
