    private function cashAccounts(): void
    { ?><section class="workspace-card"><h2><?= $this->t('خزائن الفرع في Dolibarr','Native branch cash accounts') ?></h2><div class="workspace-people"><?php foreach($this->s['accounts']as$account){ ?><span><i class="fa-solid fa-vault" aria-hidden="true"></i> <bdi><?= self::e($account['reference'].' · '.$account['currency']) ?></bdi></span><?php } ?></div><p><?= $this->t('خزنة مستقلة لكل عملة. الأرصدة والحركات من Dolibarr؛ اختيار تلقائي لا يلغي ربط الخزائن.','Each currency has its own cash account. Dolibarr owns balances and entries; automatic selection keeps these mappings active.') ?></p></section><?php }
    private function treasury(): void
    {
        $cash=$this->s['cash'];if(!$cash)return;
        if($cash['restricted']){ ?><p class="workspace-card"><?= $this->t('صلاحيتك تتيح سجلاتك فقط؛ رصيد الفرع وكشف حركته متاحان للمخوّلين بقراءة خزنة الفرع.','Your access covers your own records. Branch balances and statements require branch treasury read access.') ?></p><?php return;}
        ?><section class="workspace-treasury"><?php foreach($cash['accounts']as$account){ ?><div class="workspace-vault"><span><i class="fa-solid fa-vault" aria-hidden="true"></i> <?= self::e($account['currency']) ?></span><p><?= $this->t('الرصيد المسجّل في Dolibarr','Recorded Dolibarr cash balance') ?></p><strong><?= $this->money($account['balance'],$account['currency']) ?></strong><small><bdi><?= self::e($account['reference']) ?></bdi> · <?= $this->t('دون تحويل عملة','No currency conversion') ?><br><?= $this->t('المتاح حسب تاريخ Dolibarr','Available as of Dolibarr date') ?> <bdi><?= self::e($account['as_of']) ?></bdi>: <?= $this->money($account['available_balance'],$account['currency']) ?></small></div><?php } ?></section>
        <?php foreach($cash['accounts']as$account){ ?><section class="register-panel"><div class="workspace-register-title"><h2><?= $this->t('كشف حركة الخزنة','Native cash statement') ?> · <?= self::e($account['currency']) ?></h2><span><?= $this->t('أحدث 100 حركة كحد أقصى','Latest 100 entries maximum') ?></span></div><div class="table-scroll" tabindex="0" role="region" aria-label="<?= self::e($this->t('كشف حركة ','Cash statement ').$account['currency']) ?>"><table><thead><tr><th><?= $this->t('المرجع','Reference') ?></th><th><?= $this->t('التاريخ','Date') ?></th><th><?= $this->t('البيان','Description') ?></th><th><?= $this->t('المبلغ','Amount') ?></th></tr></thead><tbody><?php foreach($account['entries']as$entry){ ?><tr><td><bdi>#<?= $entry['id'] ?></bdi></td><td><bdi><?= self::e($entry['date']) ?></bdi></td><td><?= self::e($entry['opening']?$this->t('رصيد افتتاحي · ليس إيرادًا','Opening balance · not revenue'):$entry['label']) ?><?php if($entry['future']){ ?><small class="workspace-row-note"><?= $this->t('مؤرخة لاحقًا · غير متاحة الآن','Future dated · not available yet') ?></small><?php } ?></td><td class="workspace-amount"><?= $this->money($entry['amount'],$account['currency']) ?></td></tr><?php }if(!$account['entries']){ ?><tr><td colspan="4" class="empty"><?= $this->t('لا توجد حركات مسجلة.','No posted entries.') ?></td></tr><?php } ?></tbody></table></div><?php if($account['has_more']){ ?><p class="workspace-help"><?= $this->t('توجد حركات أقدم في سجل Dolibarr. الرصيد المعروض يشمل جميع الحركات.','Older entries exist in Dolibarr. The displayed balance includes all entries.') ?></p><?php } ?></section><?php }
    }
    private function letterhead(array $settings,?string $documentTitle=null): void
    { ?><section class="workspace-letterhead workspace-card"><?php if(!empty($settings['logo'])){ ?><img class="workspace-logo" src="<?= self::e($settings['logo']) ?>" alt="<?= self::e($settings['name']) ?>"><?php }else{ ?><span class="company-icon"><i class="fa-solid fa-building" aria-hidden="true"></i></span><?php } ?><div><h2><?= self::e($settings['name']) ?></h2><p><?= self::e($settings['phone']?:'—') ?></p></div><strong><?= self::e($documentTitle??$this->t('إيصال استلام نقدية','Cash receipt voucher')) ?></strong></section><?php }
    private function categories(): void
    { ?><div class="workspace-category-grid"><?php foreach($this->s['rows']as$row){$v=$row['content']; ?><article class="workspace-category workspace-card"><header><span class="workspace-category-icon"><i class="fa-solid fa-<?= self::e($v['icon']) ?>" aria-hidden="true"></i></span><div><h2><?= self::e($v['name']) ?></h2><small><?= self::e($row['status']==='active'&&!$v['active']?$this->t('متوقف','Inactive'):$this->status($row['status'])) ?></small></div></header><footer><?= $this->actions($row) ?></footer></article><?php }if(!$this->s['rows']){ ?><p class="workspace-card empty"><?= $this->t('لا توجد بنود مسجلة لهذا الفرع.','No categories recorded for this branch.') ?></p><?php } ?></div><?php }
    private function employeeDirectory(): void
    { ?><section class="workspace-card"><h2><?= $this->t('موظفو Dolibarr المعيّنون للفرع','Dolibarr staff assigned to this branch') ?></h2><div class="workspace-people"><?php foreach($this->s['staff']as$p){ ?><span><i class="fa-solid fa-user" aria-hidden="true"></i> <?= self::e($p['name']?:$p['login']) ?> <small><?= self::e($p['login']) ?></small></span><?php }if(!$this->s['staff'])echo self::e($this->t('لا يوجد موظفون متاحون في نطاقك.','No assigned staff available in your scope.')); ?></div><p class="workspace-help"><?= $this->t('ملف الوظيفة والراتب لا ينشئ حساب دخول جديدًا. تعيين الفروع وإلغاء الوصول من مستخدمي الشركة.','An employment profile does not create a login. Assign branches or revoke access through Company users.') ?></p></section><?php }
    private function register(): void
    {
        if($this->s['view']==='settings')return;
        $pay=$this->s['view']==='payroll';$employee=$this->s['view']==='employees';
        ?><section class="register-panel"><div class="workspace-register-title"><h2><?= $this->t('السجل','Register') ?></h2><span><?= count($this->s['rows']) ?></span></div><div class="table-scroll" tabindex="0" role="region" aria-label="<?= self::e($this->label($this->s['view'])) ?>"><table><thead><tr><th><?= $this->t('البند / الموظف','Description / employee') ?></th><th><?= $this->t('التاريخ','Date') ?></th><?php if($pay){ ?><th><?= $this->t('الإجمالي','Gross') ?></th><th><?= $this->t('سداد سلفة','Loan repayment') ?></th><?php } ?><th><?= $this->t($employee?'الراتب الأساسي':($pay?'الصافي':'المبلغ'),$employee?'Base salary':($pay?'Net':'Amount')) ?></th><th><?= $this->t('الحالة','Status') ?></th><th><?= $this->t('الإجراءات','Actions') ?></th></tr></thead><tbody><?php foreach($this->s['rows']as$row){$v=$row['content']; ?><tr><td><strong><?= self::e($employee||$pay?$this->name($v['user_id']):($v['payer']??$v['purpose']??'')) ?></strong><small class="workspace-row-note"><?= self::e($employee?$v['job']:($pay?$v['month']:$this->label($row['kind']))) ?></small></td><td><bdi><?= self::e($v['date']??$v['hired_on']??'') ?></bdi></td><?php if($pay){ ?><td><?= $this->money($v['gross'],$v['currency']) ?></td><td><?= $this->money($v['loan_repayment'],$v['currency']) ?></td><?php } ?><td class="workspace-amount"><?= $this->money($v[$employee?'salary':($pay?'net':'amount')],$v['currency']) ?></td><td><span class="status"><?= self::e($this->status($row['status'])) ?></span></td><td><?= $this->actions($row) ?></td></tr><?php }if(!$this->s['rows']){ ?><tr><td colspan="<?= $pay?7:5 ?>" class="empty"><?= $this->t('لا توجد سجلات بعد.','No records yet.') ?></td></tr><?php } ?></tbody></table></div></section><?php
        if($this->s['legacy']){ ?><details class="workspace-card"><summary><?= $this->t('المسودات السابقة ومرفقاتها','Earlier drafts and attachments') ?> (<?= count($this->s['legacy']) ?>)</summary><ul><?php foreach($this->s['legacy']as$d){ ?><li><a href="<?= self::e('index.php?'.http_build_query(['lang'=>$this->lang,'office'=>$this->s['office'],'view'=>$this->s['view'],'draft'=>$d['id']])) ?>"><?= self::e($d['purpose'].' · '.$d['amount'].' '.$d['currency'].' · '.$d['occurred_on']) ?></a></li><?php } ?></ul><p class="workspace-help"><?= $this->t('السجلات السابقة محفوظة دون تعديل، ومشمولة في تقارير المسودات.','Earlier immutable records are preserved and included in draft reports.') ?></p></details><?php }
    }
    private function actions(array $row): string
    {
        $url=$this->url(['edit'=>$row['id'],'kind'=>$row['kind']]);$html='<div class="workspace-row-actions"><a class="button button-muted" href="'.self::e($url).'#workspace-form">'.$this->t('عرض / تعديل','View / edit').'</a>';
        if(!in_array($row['kind'],['category','employee','settings'],true))$html.='<a class="button button-muted" target="_blank" rel="noopener" href="'.self::e($url.'&print=1').'">'.$this->t('طباعة','Print').'</a>';
        if($this->s['permissions']['delete']??false){$action=$row['status']==='archived'?'restore':'archive';$label=$this->t($action==='archive'?'أرشفة':'استرجاع',$action==='archive'?'Archive':'Restore');$html.='<details><summary>'.self::e($label).'</summary><form method="post" action="workspace.php">'.$this->tokens($action,$row['kind'],$row['id'],$row['revision']).'<p>'.$this->t('تُحفظ البيانات وسجل التعديلات.','Records and history are retained.').'</p><button class="button button-rose" type="submit">'.self::e($label).'</button></form></details>';}
        return $html.'</div>';
    }
    private function field(string $key,string $ar,string $en,string $type,string $value,array $options=[],bool $readOnly=false): string
    {
        $id='workspace-'.$key;$h='<div class="workspace-field"><label for="'.$id.'">'.self::e($this->t($ar,$en)).'</label>';
        if($options){$h.='<select id="'.$id.'" name="payload['.$key.']"'.($readOnly?' disabled':'').'>';foreach($options as$k=>$label)$h.='<option value="'.self::e($k).'"'.((string)$k===$value?' selected':'').'>'.self::e($label).'</option>';$h.='</select>';if($readOnly)$h.=$this->hidden('payload['.$key.']',$value);}
        elseif($type==='textarea')$h.='<textarea id="'.$id.'" name="payload['.$key.']" maxlength="2000" rows="3">'.self::e($value).'</textarea>';
        else $h.='<input id="'.$id.'" name="payload['.$key.']" type="'.($type==='money'?'text':$type).'" value="'.self::e($value).'"'.($readOnly?' readonly':'').($type==='text'?' maxlength="200"':'').($type==='money'?' inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?"':'').(in_array($key,['phone','category_ref'],true)?'':' required').'>';
        return $h.'</div>';
    }
    private function form(): void
    {
        $row=$this->s['selected'];$kind=$this->s['kind'];$v=$row['content']??[];$update=$row!==null;
        if(($update&&!($this->s['permissions']['update']??false))||(!$update&&!($this->s['permissions'][$kind==='settings'?'update':'create']??false))||($row['status']??'')==='archived')return;
        $currency=$this->s['office']==='china'?'CNY':'EGP';$h='';$field=function($key,$ar,$en,$type='text',$default='',array $options=[],bool $locked=false)use(&$v){return $this->field($key,$ar,$en,$type,(string)($v[$key]??$default),$options,$locked);};
        if(in_array($kind,['employee','payroll'],true)){$opts=[];foreach($this->s['staff']as$p)$opts[$p['id']]=($p['name']?:$p['login']).' · '.$p['login'];if($update&&!isset($opts[$v['user_id']]))$opts[$v['user_id']]='#'.$v['user_id'];if(!$opts){ ?><p class="workspace-card"><?= $this->t('يجب تعيين موظف للفرع من مستخدمي الشركة أولًا.','Assign a native staff member to this branch through Company users first.') ?></p><?php return;}$h.=$field('user_id','الموظف','Employee','text',(string)array_key_first($opts),$opts,$update);}
        if($kind==='category'){$h.=$field('name','اسم البند','Category name');$opts=array_combine(OfficeExpenseWorkspaceDocument::ICONS,OfficeExpenseWorkspaceDocument::ICONS);$h.=$field('icon','الأيقونة','Icon','text','folder',$opts);}
        if($kind==='employee'){$h.=$field('job','المسمى الوظيفي','Job title');$h.=$field('phone','الهاتف','Phone');$h.=$field('salary','الراتب الأساسي','Base salary','money','0.00');$h.=$field('hired_on','تاريخ التعيين','Hire date','date',date('Y-m-d'));}
        if(in_array($kind,['category','employee'],true)){$active=($v['active']??true)?'1':'0';$h.=$this->field('active','الحالة','Status','text',$active,['1'=>$this->t('نشط','Active'),'0'=>$this->t('متوقف','Inactive')]);}
        if($kind==='settings'){$h.=$field('name','اسم الشركة / المقر الرسمي','Official company / office name','text','China Planet');$h.=$field('phone','هاتف المقر','Office phone');$opts=['0'=>$this->t('تلقائي · خزائن الفرع حسب العملة','Automatic · branch accounts by currency')];foreach($this->s['accounts']as$account)if($account['currency']===$currency)$opts[$account['id']]=$account['label'].' · '.$account['currency'];$h.=$field('account_id','الخزنة الأساسية في Dolibarr','Primary Dolibarr cash account','text','0',$opts);}
        if($kind==='payroll'){$h.=$field('month','عن شهر','For month','month',date('Y-m'),[],$update);foreach(['base'=>['الراتب الأساسي','Base salary'],'bonus'=>['المكافآت','Bonus'],'deduction'=>['الخصومات','Deductions'],'loan_repayment'=>['سداد السلفة','Loan repayment']]as$k=>[$ar,$en])$h.=$field($k,$ar,$en,'money','0.00');}
        if(in_array($kind,['deposit','receipt','expense','advance','advance_return'],true))$h.=$field('amount','المبلغ الأصلي','Original amount','money','');
        if(!in_array($kind,['category','employee','settings'],true))$h.=$field('date','التاريخ','Date','date',date('Y-m-d'));
        if($kind==='deposit')$h.=$field('source','مصدر الأموال','Funding source');
        if($kind==='receipt'){$h.=$field('payer','استلمنا من','Received from');$h.=$field('phone','الهاتف','Phone');$h.=$field('method','طريقة الاستلام','Receipt method','text','cash',['cash'=>$this->t('نقدي','Cash'),'wallet'=>$this->t('محفظة','Wallet'),'transfer'=>$this->t('تحويل','Transfer'),'cheque'=>$this->t('شيك','Cheque')]);}
        if($kind==='expense'){$opts=[''=>$this->t('بدون بند','Uncategorized')];foreach($this->s['categories']as$c)$opts[$c['id']]=$c['content']['name'];if($update&&!isset($opts[$v['category_ref']]))$opts[$v['category_ref']]=$this->t('بند سابق','Prior category');$h.=$field('category_ref','بند المصروف','Expense category','text','',$opts);}
        if(in_array($kind,['expense','advance','advance_return'],true))$h.=$field('source_ref','مرجع المستند','Document reference');
        if($kind==='advance_return'){$opts=[];foreach($this->s['advances']as$a)$opts[$a['id']]=$a['content']['purpose'].' · '.$a['content']['amount'].' '.$a['content']['currency'];if(!$opts){ ?><p class="workspace-card"><?= $this->t('لا توجد عهدة مسجلة متاحة للربط.','No available advance request to link.') ?></p><?php return;}$h.=$field('settles_ref','العهدة المرتبطة','Linked advance','text',(string)array_key_first($opts),$update);}
        if(in_array($kind,['deposit','receipt','expense','advance','advance_return'],true))$h.=$field('purpose','وذلك مقابل / الغرض','Purpose');
        if(!in_array($kind,['category','settings'],true))$h.=$field('notes','ملاحظات','Notes','textarea');
        if($kind!=='category'){$currencies=$kind==='settings'?[$currency]:OfficeExpenseStaffAccess::OFFICES[$this->s['office']];$h.=$field('currency','العملة','Currency','text',$currency,array_combine($currencies,$currencies),$kind==='settings');}
        ?><section id="workspace-form" class="workspace-card workspace-editor"><h2><?= self::e(($update?$this->t('تعديل · ','Edit · '):$this->t('إضافة · ','Add · ')).$this->label($kind)) ?></h2><form method="post" action="workspace.php"<?= $kind==='settings'?' enctype="multipart/form-data"':'' ?>><?= $this->tokens('save',$kind,$row['id']??'',(int)($row['revision']??0)) ?><?= $this->hidden('submission_key',$this->s['submission_key']) ?><div class="workspace-form-grid"><?= $h ?></div><?php if($kind==='settings'){ ?><?= $this->hidden('payload[logo]',$v['logo']??'') ?><div class="workspace-logo-upload"><label for="workspace-logo"><?= $this->t('شعار المقر · PNG أو JPG، حتى 128 KB','Office logo · PNG or JPG, up to 128 KB') ?></label><input type="file" id="workspace-logo" name="logo" accept="image/png,image/jpeg"><label><input type="checkbox" name="payload[logo]" value=""> <?= $this->t('إزالة الشعار الحالي','Remove current logo') ?></label></div><?php } ?><div class="workspace-form-actions"><button class="button button-brand" type="submit"><i class="fa-solid fa-floppy-disk" aria-hidden="true"></i> <?= $this->t('حفظ البيانات','Save record') ?></button><?php if($update){ ?><a class="button button-muted" href="<?= self::e($this->url(['edit'=>null])) ?>"><?= $this->t('إضافة جديد','Add new') ?></a><?php } ?></div></form></section><?php
    }
    private function reports(): void
    {
        $r=$this->s['report']; ?><section class="workspace-card"><form method="get" action="workspace.php" class="workspace-report-filter"><?php foreach(['view'=>'reports','lang'=>$this->lang,'office'=>$this->s['office']]as$k=>$v)echo $this->hidden($k,$v); ?><div><label for="report-from"><?= $this->t('من تاريخ','From date') ?></label><input id="report-from" name="from" type="date" value="<?= self::e($r['from']) ?>" required></div><div><label for="report-to"><?= $this->t('إلى تاريخ','To date') ?></label><input id="report-to" name="to" type="date" value="<?= self::e($r['to']) ?>" required></div><div><label for="report-kind"><?= $this->t('نوع الطلب','Request type') ?></label><select id="report-kind" name="kind"><?php foreach(['all','expense','deposit','receipt','advance','advance_return','payroll']as$k){ ?><option value="<?= $k ?>"<?= $k===$r['filter']?' selected':'' ?>><?= self::e($k==='all'?$this->t('الكل','All'):$this->label($k)) ?></option><?php } ?></select></div><div><label for="report-status"><?= $this->t('الحالة','Status') ?></label><select id="report-status" name="status"><?php foreach(['all','draft','archived']as$k){ ?><option value="<?= $k ?>"<?= $k===$r['status']?' selected':'' ?>><?= self::e($k==='all'?$this->t('الكل','All'):$this->status($k)) ?></option><?php } ?></select></div><button class="button button-brand" type="submit"><?= $this->t('عرض التقرير','View report') ?></button><button class="button button-muted" name="export" value="csv" type="submit"><?= $this->t('تصدير CSV','Export CSV') ?></button><button class="button button-muted" type="button" data-workspace-print><?= $this->t('طباعة','Print') ?></button></form></section>
<section class="workspace-report-banner"><h2><?= $this->t('طلبات الفرع خلال الفترة','Branch requests during this period') ?></h2><p><bdi><?= self::e($r['from'].' — '.$r['to']) ?></bdi> · <?= $this->t($r['scope']==='own'?'سجلاتك فقط':'نطاق صلاحياتك داخل الفرع',$r['scope']==='own'?'Your records only':'Your permitted branch records') ?></p><div class="workspace-report-metrics"><?php foreach($r['totals']as$currency=>$totals)foreach($totals as$kind=>$total){ ?><article><span><?= self::e($this->label($kind)) ?></span><strong><?= $this->money($total,$currency) ?></strong><small><?= $this->t('مسودات قيد المراجعة','Drafts awaiting review') ?></small></article><?php }if(!$r['totals']){ ?><p><?= $this->t('لا توجد طلبات غير مؤرشفة خلال الفترة.','No unarchived requests during this period.') ?></p><?php } ?></div></section>
<section class="register-panel"><div class="workspace-register-title"><h2><?= $this->t('تفاصيل التقرير','Report details') ?></h2><span><?= count($r['rows']) ?></span></div><div class="table-scroll" tabindex="0"><table><thead><tr><th><?= $this->t('المرجع','Reference') ?></th><th><?= $this->t('النوع','Type') ?></th><th><?= $this->t('التاريخ','Date') ?></th><th><?= $this->t('البيان','Description') ?></th><th><?= $this->t('المبلغ / صافي الراتب','Amount / net salary') ?></th><th><?= $this->t('الحالة','Status') ?></th></tr></thead><tbody><?php foreach($r['rows']as$row){$v=$row['content']; ?><tr><td><bdi><?= self::e(substr($row['id'],0,12)) ?></bdi></td><td><?= self::e($this->label($row['kind'])) ?></td><td><bdi><?= self::e($v['date']) ?></bdi></td><td><?= self::e($v['purpose']??$v['notes']??'') ?></td><td class="workspace-amount"><?= $this->money($v[$row['kind']==='payroll'?'net':'amount'],$v['currency']) ?></td><td><?= self::e($this->status($row['status'])) ?></td></tr><?php } ?></tbody></table></div></section><?php
    }
    private function printDocument(array $row): void
    {
        $v=$row['content'];$this->letterhead($this->s['settings']??['name'=>'China Planet','phone'=>''],$this->label($row['kind'])); ?><article class="workspace-card workspace-print-document"><h2><?= self::e($this->label($row['kind'])) ?></h2><p class="workspace-print-draft"><?= self::e($this->status($row['status'])) ?></p><dl><dt><?= $this->t('المرجع','Reference') ?></dt><dd><bdi><?= self::e($row['id']) ?></bdi></dd><?php foreach($v as$k=>$value){if(in_array($k,['category_ref','settles_ref','source_ref'],true)&&$value==='')continue; ?><dt><?= self::e($this->fieldLabel($k)) ?></dt><dd><?= self::e($k==='user_id'?$this->name((int)$value):$value) ?></dd><?php } ?></dl><p><?= $this->t('إعداد الطلب / التوقيع: ____________________','Prepared by / signature: ____________________') ?></p><button class="button button-brand" type="button" data-workspace-print><?= $this->t('طباعة / حفظ PDF','Print / save PDF') ?></button></article><?php
    }
    private function details(array $row): void
    { ?><section class="workspace-card"><h2><?= self::e($this->label($row['kind'])) ?></h2><dl><?php foreach($row['content']as$key=>$value){ ?><dt><?= self::e($this->fieldLabel($key)) ?></dt><dd><?= self::e(is_bool($value)?$this->t($value?'نشط':'متوقف',$value?'Active':'Inactive'):$value) ?></dd><?php } ?></dl></section><?php }
    private function fieldLabel(string $k): string
    {
        $labels=['user_id'=>['الموظف','Employee'],'date'=>['التاريخ','Date'],'month'=>['الشهر','Month'],'base'=>['الأساسي','Base'],'bonus'=>['مكافأة','Bonus'],'deduction'=>['الخصومات','Deductions'],'loan_repayment'=>['سداد سلفة','Loan repayment'],'gross'=>['الإجمالي','Gross'],'net'=>['الصافي','Net'],'amount'=>['المبلغ','Amount'],'currency'=>['العملة','Currency'],'payer'=>['استلمنا من','Received from'],'phone'=>['الهاتف','Phone'],'method'=>['الطريقة','Method'],'purpose'=>['الغرض','Purpose'],'notes'=>['ملاحظات','Notes'],'source'=>['المصدر','Source'],'source_ref'=>['مرجع المستند','Source reference'],'category_ref'=>['مرجع البند','Category reference'],'settles_ref'=>['مرجع العهدة','Advance reference']];return $labels[$k][$this->ar?0:1]??$k;
    }
}
